package com.aicharacter.v3;
/** Recovers legacy/stalled ACTIVE plans without teleporting or repeatedly clearing them. */
public final class PlanIntegrityChecker{private static final long STALL_RECOVERY_MS=15000L;private PlanIntegrityChecker(){}
 public static String check(WorldState s,long now){PlanState p=s.planState;if(p==null||!"ACTIVE".equals(p.status))return"OK";if(s.girlTravel.active)return"TRAVELLING";String dest=routeDestination(s,p);WorldArea here=s.world.areaAt(s.haruX);boolean atDestination=here!=null&&!dest.isEmpty()&&here.id.equals(dest);if(atDestination&&!p.plannedAction.isEmpty()){PlanExecutor.executeAction(s,now);return"RECOVERED_PENDING_ACTION";}if(now-p.lastProgressAt>STALL_RECOVERY_MS&&!dest.isEmpty()){if(TravelEngine.start(s,s.girlTravel,"girl",dest,p.planId,now)){p.lastReason="watchdog restarted physical travel";p.lastProgressAt=now;return"REPLANNED";}fail(s,p,now,"watchdog: destination unreachable");return"FAILED";}if(now-p.lastProgressAt>STALL_RECOVERY_MS&&dest.isEmpty()){fail(s,p,now,"watchdog: destination no longer exists");return"FAILED";}return"WAITING";}
 private static String routeDestination(WorldState s,PlanState p){if(p==null||p.destination==null||p.destination.isEmpty())return"";WorldObject o=s.world.object(p.destination);if(o!=null)return o.areaId;WorldArea a=s.world.area(p.destination);return a==null?"":a.id;}
 private static void fail(WorldState s,PlanState p,long now,String outcome){p.status="FAILED";p.lastProgressAt=now;s.currentIntention="";s.persistentIntentionTarget="";s.intentionStartedAt=now;s.haruActivity="pausing after a plan became impossible";p.lastOutcome=outcome;WorldEventBus.publishId(s,now,"plan_integrity_"+p.planId,"PLAN_INTEGRITY_FAILED",p.planId,outcome);PlanExecutor.learnTerminalOutcome(s,p,now,"plan_integrity_failed",outcome,true);s.developerReports.add(new DeveloperReport(now,"PLAN_INTEGRITY","MEDIUM","PlanIntegrityChecker",outcome,"invalid or stale route target","plan="+p.planId,"failed safely; no teleport"));while(s.developerReports.size()>80)s.developerReports.remove(0);}
}
